import itertools, json
A=[('KMP',{2,7}),('LNP',{1,6,7}),('KLN',{7}),('MQR',{8}),('LMQ',{2,7})]
B=[('LPQ',{4,6}),('NPR',{3}),('LMP',{2,8}),('MNR',{3}),('KNP',{6,7,8})]
people=set('KLMNPQR'); west=set('KPR')
def assignments(rows):
    return [x for x in itertools.product(*(r[0] for r in rows)) if len(set(x))==5]
a=assignments(A); b=assignments(B)
count=0; histogram={}; witnesses={}
for x in a:
    for y in b:
        joint=set(x)&set(y)
        if len(joint)!=3 or len(joint&west)!=1: continue
        days={p:set() for p in people}
        for ids,rows in [(x,A),(y,B)]:
            for p,(_,ds) in zip(ids,rows): days[p].update(ds)
        n=sum(len(ds)>=3 for ds in days.values())
        count+=1; histogram[n]=histogram.get(n,0)+1
        witnesses.setdefault(n,{'A':''.join(x),'B':''.join(y)})
lo=min(histogram); hi=max(histogram)
result={'feasible_linkages':count,'bounds':[lo,hi],'low_witness':witnesses[lo],'high_witness':witnesses[hi],'decision':'confirmed' if lo>=4 else 'excluded' if hi<4 else 'undetermined'}
print(json.dumps(result))
print('diagnostics',len(a),len(b),histogram)
for n in [lo,hi]:
    w=witnesses[n]; d={p:set() for p in people}
    for key,rows in [('A',A),('B',B)]:
        for p,(_,ds) in zip(w[key],rows):d[p].update(ds)
    print(n, {p:sorted(ds) for p,ds in sorted(d.items())})

